class Solution {
public:
    int kIncreasing(vector<int>& arr, int k) {
        int n = arr.size();
        int ans = 0;
        for (int i = 0; i < k; ++i) {
            vector<int> tails;
            for (int j = i; j < n; j += k) {
                auto it = upper_bound(tails.begin(), tails.end(), arr[j]);
                if (it == tails.end()) {
                    tails.push_back(arr[j]);
                } else {
                    *it = arr[j];
                }
            }
            int len = (n - i - 1) / k + 1;
            ans += len - (int)tails.size();
        }
        return ans;
    }
};
